//! 剪贴板流水（SENSE.md 7.1.1）。默认关，作者在口袋里打开后才开始记。
//!
//! - 复制：轮询 NSPasteboard 的 changeCount（0.5 秒），只取文本，记来源 app。
//! - 去向：macOS 不告诉你粘到了哪；不监听按键（那要"辅助功能"权限），
//!   改为记复制后 10 分钟内第一个切到的前台 app，页面上标"之后切到"。
//! - 读取边界：密码管理器打的 Concealed / Transient / AutoGenerated 标、聊天与邮件 app、
//!   密钥 / 邮箱 / 电话 / 卡号 / 长 hex 样式，整条丢弃，不脱敏保留。

use objc2_app_kit::{NSPasteboard, NSPasteboardTypePNG, NSPasteboardTypeString, NSWorkspace};
use objc2_foundation::NSData;
use serde::Serialize;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use tauri::{AppHandle, Emitter};

/// ⌃⌘A 截完的图也放一份到系统剪贴板，和 macOS 自带的 ⌃⇧⌘4 一样，任何 app 里 ⌘V 都能贴。
/// 流水只记文本，所以这张图不会被记成一条复制。
pub fn put_png(bytes: &[u8]) -> bool {
    let pb = NSPasteboard::generalPasteboard();
    pb.clearContents();
    let data = NSData::with_bytes(bytes);
    unsafe { pb.setData_forType(Some(&data), NSPasteboardTypePNG) }
}

pub static WATCH: AtomicBool = AtomicBool::new(false);

const SKIP_TYPES: &[&str] = &["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"];
/// 来源是这些 app 的不记：多半是别人写的话，或是密码。
const SKIP_APPS: &[&str] = &[
    "com.tencent.xinWeChat", "jp.naver.line.mac", "com.tinyspeck.slackmacgap", "com.apple.MobileSMS", "com.apple.mail",
    "com.microsoft.Outlook", "com.hnc.Discord", "ru.keepcoder.Telegram", "net.whatsapp.WhatsApp", "com.facebook.archon",
    "com.1password.1password", "com.agilebits.onepassword7", "com.bitwarden.desktop", "com.apple.keychainaccess", "com.apple.Passwords",
];

#[derive(Clone, Serialize)]
struct Copy {
    id: String,
    text: String,
    from_app: String,
    from_bundle: String,
    at: u128,
}

#[derive(Clone, Serialize)]
struct CopyTo {
    id: String,
    to_app: String,
    to_bundle: String,
    after_s: u64,
}

fn now_ms() -> u128 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_millis()).unwrap_or(0)
}

fn front() -> (String, String) {
    let ws = NSWorkspace::sharedWorkspace();
    match ws.frontmostApplication() {
        Some(a) => (
            a.localizedName().map(|s| s.to_string()).unwrap_or_default(),
            a.bundleIdentifier().map(|s| s.to_string()).unwrap_or_default(),
        ),
        None => (String::new(), String::new()),
    }
}

fn sensitive(t: &str) -> bool {
    let low = t.to_lowercase();
    if ["-----begin", "password", "passwd", "密码", "パスワード", "secret", "token=", "api_key", "apikey", "bearer "].iter().any(|k| low.contains(k)) {
        return true;
    }
    if ["sk-", "ghp_", "gho_", "xoxb-", "xoxp-", "akia", "aiza"].iter().any(|k| low.contains(k)) {
        return true;
    }
    // 邮箱
    if t.split_whitespace().any(|w| w.contains('@') && w.contains('.') && !w.starts_with('@')) {
        return true;
    }
    // 连续数字（电话、卡号）：去掉空格和横线后 ≥10 位
    let mut run = 0;
    for c in t.chars() {
        if c.is_ascii_digit() {
            run += 1;
            if run >= 10 {
                return true;
            }
        } else if c != ' ' && c != '-' {
            run = 0;
        }
    }
    // ≥32 位 hex / base64 样式的单词；短单行且无空格的混合串多半是口令
    let words: Vec<&str> = t.split_whitespace().collect();
    if words.iter().any(|w| w.len() >= 32 && w.chars().all(|c| c.is_ascii_alphanumeric() || "+/=_-".contains(c)) && !w.starts_with("http")) {
        return true;
    }
    if words.len() == 1 && t.len() >= 8 && t.len() <= 64 && !t.starts_with("http") {
        let (u, l, d, s) = t.chars().fold((0, 0, 0, 0), |(u, l, d, s), c| {
            (u + c.is_ascii_uppercase() as u8, l + c.is_ascii_lowercase() as u8, d + c.is_ascii_digit() as u8, s + (c.is_ascii_punctuation()) as u8)
        });
        if u > 0 && l > 0 && d > 0 && s > 0 {
            return true;
        }
    }
    false
}

pub fn start(app: AppHandle, self_bundle: String) {
    std::thread::spawn(move || {
        let pb = NSPasteboard::generalPasteboard();
        let mut last = pb.changeCount();
        let mut pending: Option<(String, String, Instant)> = None; // id, 来源 bundle, 时间
        let mut prev_front = String::new();
        loop {
            std::thread::sleep(Duration::from_millis(500));
            let on = WATCH.load(Ordering::Relaxed);
            let cc = pb.changeCount();
            let (fname, fbundle) = front();
            if let Some((id, src, t0)) = pending.clone() {
                if t0.elapsed() > Duration::from_secs(600) {
                    pending = None;
                } else if !fbundle.is_empty() && fbundle != src && fbundle != prev_front {
                    if fbundle != self_bundle {
                        let _ = app.emit("sense://copy-to", CopyTo { id, to_app: fname.clone(), to_bundle: fbundle.clone(), after_s: t0.elapsed().as_secs() });
                    }
                    pending = None;
                }
            }
            prev_front = fbundle.clone();
            if cc == last {
                continue;
            }
            last = cc;
            if !on || fbundle == self_bundle || SKIP_APPS.contains(&fbundle.as_str()) {
                continue;
            }
            let types: Vec<String> = pb.types().map(|a| a.iter().map(|t| t.to_string()).collect()).unwrap_or_default();
            if types.iter().any(|t| SKIP_TYPES.iter().any(|s| t.contains(s))) {
                continue;
            }
            let text = match unsafe { pb.stringForType(NSPasteboardTypeString) } {
                Some(s) => s.to_string(),
                None => continue, // 只记文本；图片走 ⌃⌘A
            };
            let text = text.trim();
            if text.chars().count() < 4 || text.len() > 20_000 || sensitive(text) {
                continue;
            }
            let id = format!("K{}", now_ms());
            let short: String = text.chars().take(2000).collect();
            let _ = app.emit("sense://copy", Copy { id: id.clone(), text: short, from_app: fname, from_bundle: fbundle.clone(), at: now_ms() });
            pending = Some((id, fbundle, Instant::now()));
        }
    });
}
